import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as n,o as e,af as s}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"Zhipu Qingyan / Z.ai learning map","description":"Audience: frontend engineers picking a Zhipu chat surface. The path here is Qingyan and Z.ai chat, not GLM Coding Plan.","frontmatter":{"title":"Zhipu Qingyan / Z.ai learning map","description":"Audience: frontend engineers picking a Zhipu chat surface. The path here is Qingyan and Z.ai chat, not GLM Coding Plan.","domain":"product","tags":["coding-agent"],"role":"map"},"headers":[],"relativePath":"products/zhipu-chat/index.md","filePath":"products/zhipu-chat/index.md","lastUpdated":1787110548000}'),i={name:"products/zhipu-chat/index.md"};function o(r,a,l,p,d,h){return e(),n("div",null,[...a[0]||(a[0]=[s(`<h1 id="zhipu-qingyan-z-ai-learning-map" tabindex="-1">Zhipu Qingyan / Z.ai learning map <a class="header-anchor" href="#zhipu-qingyan-z-ai-learning-map" aria-label="Permalink to &quot;Zhipu Qingyan / Z.ai learning map&quot;">​</a></h1><blockquote><p><strong>Zhipu Qingyan</strong> (智谱清言) is Zhipu&#39;s China chat assistant. Official line (<a href="https://chatglm.cn" target="_blank" rel="noreferrer">chatglm.cn</a>): it is based on GLM models, &quot;not just an AI assistant, but an Agent that gets things done.&quot;</p><p><strong>Z.ai</strong> is the international chat surface. Official title (<a href="https://chat.z.ai" target="_blank" rel="noreferrer">chat.z.ai</a>): &quot;Z.ai - Advanced AI Chatbot &amp; Agent powered by GLM-5.2&quot;</p><p>This directory is the Claude.ai analog. It is <strong>not</strong> GLM Coding Plan and not ZCode / AutoClaw. The coding subscription is one row on the map.</p></blockquote><h2 id="goals-and-non-goals" tabindex="-1">Goals and non-goals <a class="header-anchor" href="#goals-and-non-goals" aria-label="Permalink to &quot;Goals and non-goals&quot;">​</a></h2><p><strong>Audience:</strong> frontend engineers who need the right official door. You need a browser or the Qingyan app, not a repo.</p><p><strong>Goals:</strong> list official first-party AI surfaces and get you into Qingyan / Z.ai chat.</p><p><strong>Non-goals:</strong> Coding Plan install, API quickstart, model internals (see <a href="/tech/fundamentals/LLM.html">Learn LLM</a>), invented daily quotas or RMB prices.</p><h2 id="product-landscape" tabindex="-1">Product landscape <a class="header-anchor" href="#product-landscape" aria-label="Permalink to &quot;Product landscape&quot;">​</a></h2><p>Zhipu (company site <a href="https://www.zhipuai.cn/zh" target="_blank" rel="noreferrer">zhipuai.cn</a>) ships more than one AI skin. They are <strong>not</strong> the same chat window.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Zhipu / Z.ai</span></span>
<span class="line"><span>├── Chat (this directory)</span></span>
<span class="line"><span>│   ├── Qingyan — chatglm.cn and the official app</span></span>
<span class="line"><span>│   └── Z.ai — chat.z.ai / z.ai</span></span>
<span class="line"><span>├── Coding subscription / desktop coding</span></span>
<span class="line"><span>│   ├── GLM Coding Plan — quota for Claude Code and similar tools</span></span>
<span class="line"><span>│   └── ZCode — official coding tool</span></span>
<span class="line"><span>├── Agent / office</span></span>
<span class="line"><span>│   ├── AutoGLM</span></span>
<span class="line"><span>│   └── AutoClaw (local OpenClaw client)</span></span>
<span class="line"><span>├── Open platform / API</span></span>
<span class="line"><span>│   ├── BigModel (bigmodel.cn)</span></span>
<span class="line"><span>│   └── docs.z.ai</span></span>
<span class="line"><span>└── Other official AI entries (one map row each)</span></span>
<span class="line"><span>    ├── Zread.ai</span></span>
<span class="line"><span>    ├── AMiner</span></span>
<span class="line"><span>    ├── Zhipu Learning Center</span></span>
<span class="line"><span>    ├── Zhipu AI IME</span></span>
<span class="line"><span>    ├── CodeGeeX</span></span>
<span class="line"><span>    └── Open GLM weights</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Product</th><th>What it is</th><th>Entry</th><th>This site</th></tr></thead><tbody><tr><td><strong>Qingyan</strong></td><td>China chat / agent assistant</td><td><a href="https://chatglm.cn" target="_blank" rel="noreferrer">chatglm.cn</a></td><td><a href="./zhipu-chat.html">Tutorial</a></td></tr><tr><td><strong>Z.ai chat</strong></td><td>International chat / agent assistant</td><td><a href="https://chat.z.ai" target="_blank" rel="noreferrer">chat.z.ai</a></td><td>Same tutorial</td></tr><tr><td><strong>GLM Coding Plan</strong></td><td>Coding-tool subscription, not a chat install</td><td><a href="https://z.ai/subscribe" target="_blank" rel="noreferrer">z.ai/subscribe</a>, <a href="https://bigmodel.cn/glm-coding" target="_blank" rel="noreferrer">bigmodel.cn/glm-coding</a></td><td>One map row (#75)</td></tr><tr><td><strong>ZCode</strong></td><td>Official coding tool</td><td><a href="https://zcode.z.ai/cn" target="_blank" rel="noreferrer">zcode.z.ai/cn</a></td><td>One map row</td></tr><tr><td><strong>AutoGLM / AutoClaw</strong></td><td>Reports / browser agent / local client</td><td><a href="https://autoglm.zhipuai.cn" target="_blank" rel="noreferrer">autoglm.zhipuai.cn</a></td><td>One map row</td></tr><tr><td><strong>BigModel / Z.ai API</strong></td><td>Model HTTP APIs</td><td><a href="https://bigmodel.cn" target="_blank" rel="noreferrer">bigmodel.cn</a>, <a href="https://docs.z.ai" target="_blank" rel="noreferrer">docs.z.ai</a></td><td>One map row</td></tr><tr><td><strong>Zread.ai / AMiner / Learning Center / AI IME</strong></td><td>Named on the company product rail</td><td><a href="https://www.zhipuai.cn/zh" target="_blank" rel="noreferrer">zhipuai.cn/zh</a></td><td>One map row; use the company page for URLs</td></tr><tr><td><strong>CodeGeeX</strong></td><td>Coding assistant (official news)</td><td><a href="https://www.zhipuai.cn/en/news/20" target="_blank" rel="noreferrer">company news</a></td><td>One map row</td></tr><tr><td><strong>Open GLM</strong></td><td>Model weights</td><td><a href="https://github.com/zai-org/GLM-5" target="_blank" rel="noreferrer">github.com/zai-org/GLM-5</a></td><td>One map row</td></tr><tr><td>Business / IR / jobs</td><td>Not an AI handbook</td><td>Company site</td><td><strong>Out of scope</strong></td></tr></tbody></table><p>Official &quot;try it online&quot; copy (<a href="https://www.zhipuai.cn/zh/research/161" target="_blank" rel="noreferrer">GLM-5.2 research post</a>): <strong>Z.ai = chat.z.ai</strong>, <strong>Qingyan app/web = chatglm.cn</strong>.</p><p><strong>Name collisions:</strong></p><ul><li><strong>Qingyan ≠ Z.ai chat.</strong> Two doors, two legal entities. No official &quot;one login&quot;.</li><li><strong>ChatGLM</strong> is a historical model / store-copy name, not the URL you type.</li><li><strong>In-chat code ≠ GLM Coding Plan.</strong> The latter is quota for Claude Code and similar tools. See #75.</li><li><strong>AutoGLM ≠ AutoClaw.</strong> The company page lists both.</li></ul><p>Details: <a href="./zhipu-chat-glossary.html">glossary</a>.</p><h3 id="quick-decision" tabindex="-1">Quick decision <a class="header-anchor" href="#quick-decision" aria-label="Permalink to &quot;Quick decision&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>What do you need?</span></span>
<span class="line"><span>├── Chat / write / read images or docs / slides or research reports</span></span>
<span class="line"><span>│   ├── China product surface → Qingyan (chatglm.cn or the official app)</span></span>
<span class="line"><span>│   └── International Z.ai surface → chat.z.ai</span></span>
<span class="line"><span>├── GLM quota inside Claude Code / Cline / similar</span></span>
<span class="line"><span>│   └── → GLM Coding Plan (not documented here)</span></span>
<span class="line"><span>├── Official desktop coding tool</span></span>
<span class="line"><span>│   └── → ZCode</span></span>
<span class="line"><span>├── Reports / browser automation / local OpenClaw client</span></span>
<span class="line"><span>│   └── → AutoGLM / AutoClaw</span></span>
<span class="line"><span>└── Call the model from your own software</span></span>
<span class="line"><span>    └── → BigModel or docs.z.ai API</span></span></code></pre></div><h2 id="learning-path" tabindex="-1">Learning path <a class="header-anchor" href="#learning-path" aria-label="Permalink to &quot;Learning path&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Stage</th><th>Read</th><th>Goal</th></tr></thead><tbody><tr><td>1. Pick the door</td><td>Decision tree above</td><td>Do not open Coding Plan as if it were Qingyan</td></tr><tr><td>2. Use chat</td><td><a href="./zhipu-chat.html">Qingyan / Z.ai tutorial</a></td><td>Sign in, send the first message, recognize the chips</td></tr><tr><td>3. Look up URLs</td><td><a href="./zhipu-chat-cheatsheet.html">Cheatsheet</a></td><td>Entries, decisions, sources</td></tr><tr><td>4. Names collide</td><td><a href="./zhipu-chat-glossary.html">Glossary</a></td><td>Qingyan / Z.ai / ChatGLM / Coding Plan</td></tr></tbody></table><p>No cookbook: there is no official how-to tree dense enough to split.</p><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./zhipu-chat.html">Qingyan / Z.ai tutorial</a></li><li><a href="./zhipu-chat-cheatsheet.html">Cheatsheet</a></li><li><a href="./zhipu-chat-glossary.html">Glossary</a></li><li><a href="./../">All products</a></li></ul>`,21)])])}const b=t(i,[["render",o]]);export{m as __pageData,b as default};
